insert into public.categories(name,slug,description,display_order) values ('AI','ai','Machine learning and intelligent systems',1),('Cybersecurity','cybersecurity','Security research and resilient systems',2),('Full Stack','full-stack','End to end web applications',3),('Mobile','mobile','Applications for mobile platforms',4),('Big Data','big-data','Data platforms and distributed processing',5),('IoT','iot','Connected devices and embedded systems',6) on conflict(slug) do nothing;
insert into public.technologies(name) values ('Python'),('PyTorch'),('TensorFlow'),('Scikit-learn'),('OpenCV'),('YOLO'),('LLM'),('LangChain'),('OpenAI API'),('Multi-Agent Systems'),('Cyber Threat Intelligence'),('Networking'),('Cybersecurity'),('React'),('Node.js'),('Express'),('MongoDB'),('FastAPI'),('REST API'),('React Native'),('Firebase'),('JavaScript'),('Hadoop'),('HDFS'),('MapReduce'),('Big Data'),('AWS IoT Core'),('MQTT'),('AWS'),('IoT'),('ESP32'),('RPL'),('Embedded Systems') on conflict(name) do nothing;
insert into public.projects(category_id,title,slug,short_description,description,display_order,published) select c.id,v.title,v.slug,'Project overview to be added.','Add your project details from the admin dashboard.',v.n,false from (values ('AI','Deep Learning','deep-learning',1),('AI','Computer Vision','computer-vision',2),('AI','Generative AI','generative-ai',3),('Cybersecurity','CTI Multi-Agent System','cti-multi-agent-system',1),('Cybersecurity','Network Security','network-security',2),('Full Stack','React + Node.js','react-nodejs',1),('Full Stack','React + FastAPI','react-fastapi',2),('Mobile','PropertyFinderApp','propertyfinderapp',1),('Big Data','Hadoop E-commerce','hadoop-ecommerce',1),('IoT','AWS IoT','aws-iot',1),('IoT','RPL / ESP32','rpl-esp32',2)) v(cat,title,slug,n) join public.categories c on c.slug=case v.cat when 'Full Stack' then 'full-stack' when 'Big Data' then 'big-data' else lower(replace(v.cat,' ','-')) end on conflict(slug) do nothing;
insert into public.project_technologies(project_id,technology_id) select p.id,t.id from (values ('deep-learning','Python'),('deep-learning','PyTorch'),('deep-learning','TensorFlow'),('deep-learning','Scikit-learn'),('computer-vision','Python'),('computer-vision','OpenCV'),('computer-vision','YOLO'),('computer-vision','PyTorch'),('generative-ai','Python'),('generative-ai','LLM'),('generative-ai','LangChain'),('generative-ai','OpenAI API'),('cti-multi-agent-system','Python'),('cti-multi-agent-system','Multi-Agent Systems'),('cti-multi-agent-system','LLM'),('cti-multi-agent-system','Cyber Threat Intelligence'),('network-security','Python'),('network-security','Networking'),('network-security','Cybersecurity'),('react-nodejs','React'),('react-nodejs','Node.js'),('react-nodejs','Express'),('react-nodejs','MongoDB'),('react-fastapi','React'),('react-fastapi','FastAPI'),('react-fastapi','Python'),('react-fastapi','REST API'),('propertyfinderapp','React Native'),('propertyfinderapp','Firebase'),('propertyfinderapp','JavaScript'),('hadoop-ecommerce','Hadoop'),('hadoop-ecommerce','HDFS'),('hadoop-ecommerce','MapReduce'),('hadoop-ecommerce','Big Data'),('aws-iot','AWS IoT Core'),('aws-iot','MQTT'),('aws-iot','AWS'),('aws-iot','IoT'),('rpl-esp32','ESP32'),('rpl-esp32','RPL'),('rpl-esp32','IoT'),('rpl-esp32','Embedded Systems')) v(slug,name) join public.projects p on p.slug=v.slug join public.technologies t on t.name=v.name on conflict do nothing;
